   "  cfg.combos = cfg.combos || [];\n  cfg.colores = cfg.colores || [];\n  CV_SEL = { activos: [], desc: {}, precio: {}, fuente: {}, color: CV_BASE, libres: [], aviso: '', descPaq: {}, cliente: { nombre: '', telefono: '', tipo: 'publico' },\n            entrega: 'recoge', flete: null, fleteCp: '', fleteEstado: '', fleteError: '', fleteCpOrigen: (typeof fac_cpOrigenGuardado === 'function' ? fac_cpOrigenGuardado() : '') };\n  (cfg.combos || []).filter(cb => cb.por_defecto).forEach(cb => cv_aplicarPaquete(cb));\n  CV_SEL.desc[CV_BASE] = Number(cfg.base.descuento_pct) || 0;\n  cfg.accesorios.forEach(a => { CV_SEL.desc[a.uid] = Number(a.descuento_pct) || 0; });\n",
   "  cfg.combos = cfg.combos || [];\n  cfg.colores = cfg.colores || [];\n  CV_SEL = { activos: [], desc: {}, precio: {}, fuente: {}, color: CV_BASE, libres: [], aviso: '', descPaq: {}, cliente: { nombre: '', telefono: '', tipo: 'publico' },\n            entrega: 'recoge', flete: null, fleteCp: '', fleteEstado: '', fleteError: '', fleteCpOrigen: (typeof fac_cpOrigenGuardado === 'function' ? fac_cpOrigenGuardado() : ''),\n            est: cv_est_nuevo() };\n  await cv_est_cargarCfg();\n  (cfg.combos || []).filter(cb => cb.por_defecto).forEach(cb => cv_aplicarPaquete(cb));\n  CV_SEL.desc[CV_BASE] = Number(cfg.base.descuento_pct) || 0;\n  cfg.accesorios.forEach(a => { CV_SEL.desc[a.uid] = Number(a.descuento_pct) || 0; });\n"
