   "function cv_htmlFlete() {\n  const inst = CV_SEL.entrega === 'instalamos';\n  const f = CV_SEL.flete;\n  return `\n    <span class=\"cv-etq\">🚚 Entrega</span>\n    <div style=\"display:flex; gap:6px; flex-wrap:wrap;\">\n      <button type=\"button\" class=\"${inst ? 'secondary' : 'primary'}\" style=\"flex:1;\" onclick=\"cv_setEntrega('recoge')\">El cliente lo recoge</button>\n      <button type=\"button\" class=\"${inst ? 'primary' : 'secondary'}\" style=\"flex:1;\" onclick=\"cv_setEntrega('instalamos')\">Se lo llevamos e instalamos</button>\n    </div>\n    ${inst ? `\n      <div class=\"cv-caja\" style=\"margin-top:8px;\">\n        <div class=\"row-2\">\n",
   "function cv_htmlFlete() {\n  const inst = CV_SEL.entrega === 'instalamos';\n  const f = CV_SEL.flete;\n  const boton = (v, texto) => `<button type=\"button\" class=\"${CV_SEL.entrega === v ? 'primary' : 'secondary'}\" style=\"flex:1; min-width:120px;\" onclick=\"cv_setEntrega('${v}')\">${texto}</button>`;\n  return `\n    <span class=\"cv-etq\">🚚 Entrega</span>\n    <div style=\"display:flex; gap:6px; flex-wrap:wrap;\">\n      ${boton('recoge', 'El cliente lo recoge')}${boton('instalamos', 'Se lo llevamos e instalamos')}${boton('estafeta', '📦 Paquetería Estafeta')}\n    </div>\n    ${CV_SEL.entrega === 'estafeta' ? cv_est_html() : ''}\n    ${inst ? `\n      <div class=\"cv-caja\" style=\"margin-top:8px;\">\n        <div class=\"row-2\">\n"
