   "    }\n  });\n  cv_renderCotizar();\n}\n\n// ---------- Conceptos libres (envío, paquetería, instalación…) ----------\n",
   "    }\n  });\n  cv_renderCotizar();\n}\n\n// ---------- Envío por paquetería Estafeta (al cotizar) ----------\n// Tercera opción de 🚚 Entrega: sucursal de origen + CP del cliente + peso y\n// medidas → precios de la cuenta Estafeta de la empresa (+ margen que pone el\n// admin). El servicio elegido entra como renglón \"Envío por paquetería\n// Estafeta\" (clave ESTAFETA). La guía y el rastreo se hacen después, desde la\n// cotización (📦 Guía Estafeta).\n\nlet CV_EST_CFG = null;\n\nfunction cv_est_nuevo() {\n  let medidas = {};\n  try { medidas = JSON.parse(localStorage.getItem('cv_est_medidas') || '{}') || {}; } catch (e) { medidas = {}; }\n  return { origenId: null, cp: '', peso: medidas.peso || '', largo: medidas.largo || '', ancho: medidas.ancho || '', alto: medidas.alto || '',\n           res: null, servicioId: null, error: '' };\n}\n\nasync function cv_est_cargarCfg() {\n  try { CV_EST_CFG = await api('/api/estafeta/config'); } catch (e) { CV_EST_CFG = null; }\n  return CV_EST_CFG;\n}\n\nfunction cv_est_servicio() {\n  const e = CV_SEL && CV_SEL.est;\n  if (!e || !e.res) return null;\n  return (e.res.servicios || []).find(s => s.servicio_id === e.servicioId) || null;\n}\n\nfunction cv_est_linea() {\n  const s = cv_est_servicio();\n  if (!s) return [];\n  const e = CV_SEL.est, precio = Number(s.precio) || 0;\n  const nota = `${s.servicio}${s.dias ? ` · ${s.dias}` : ''} · De ${e.res.origen.nombre} (CP ${e.res.origen.cp}) a CP ${e.res.cp_destino} · ${e.res.paquete.peso} kg, ${e.res.paquete.largo}×${e.res.paquete.ancho}×${e.res.paquete.alto} cm`;\n  return [{ uid: 'ESTAFETA', p: { nombre: (CV_EST_CFG && CV_EST_CFG.nombre_item) || 'Envío por paquetería Estafeta', clave: 'ESTAFETA' },\n            precio, desc: 0, combos: [], descEfectivo: 0, neto: precio, libre: true, flete: true, cantidad: 1, precio_unitario: precio, nota }];\n}\n\nfunction cv_est_envioPayload() {\n  const s = cv_est_servicio();\n  if (!s || CV_SEL.entrega !== 'estafeta') return null;\n  const r = CV_SEL.est.res;\n  return { origen_id: r.origen.id, origen_nombre: r.origen.nombre, cp_origen: r.origen.cp, cp_destino: r.cp_destino, paquete: r.paquete,\n           servicio_id: s.servicio_id, servicio: s.servicio, dias: s.dias || null, precio: s.precio, simulado: !!r.simulado, cotizado_en: r.cotizado_en };\n}\n\nfunction cv_est_html() {\n  const cfg = CV_EST_CFG, e = CV_SEL.est;\n  if (!cfg) return '<div class=\"cv-aviso\" style=\"margin-top:8px;\">⚠️ No se pudo leer la configuración de Estafeta.</div>';\n  if (!cfg.estado.modo) return `<div class=\"cv-aviso\" style=\"margin-top:8px;\">📦 Estafeta todavía no está conectada${cv_esAdmin() ? ' — faltan las credenciales de la cuenta en Render (ver 📦 Estafeta en la lista de equipos).' : ' — avísale al administrador.'}</div>`;\n  if (!cfg.origenes.filter(o => o.activo).length) return `<div class=\"cv-aviso\" style=\"margin-top:8px;\">📦 Falta dar de alta la sucursal de donde salen los paquetes${cv_esAdmin() ? ' (📦 Estafeta en la lista de equipos).' : ' — avísale al administrador.'}</div>`;\n  if (!e.origenId) e.origenId = cfg.origenes.find(o => o.activo).id;\n  const num = (k, etq, paso) => `<div class=\"field\" style=\"margin:0;\"><label>${etq}</label><input inputmode=\"decimal\" type=\"number\" min=\"0\" step=\"${paso}\" value=\"${escapeHtml(String(e[k] ?? ''))}\" oninput=\"CV_SEL.est['${k}']=this.value\" /></div>`;\n  const s = cv_est_servicio();\n  const cambio = e.res && (String(e.res.cp_destino) !== (e.cp || '').trim() || Number(e.res.origen.id) !== Number(e.origenId));\n  return `\n    <div class=\"cv-caja\" style=\"margin-top:8px;\">\n      ${cfg.estado.simulado ? '<div class=\"cv-aviso\" style=\"margin-bottom:8px;\">🧪 Modo SIMULADO: precios de prueba, no son de Estafeta.</div>' : ''}\n      <div class=\"row-2\">\n        <div class=\"field\" style=\"margin:0;\"><label>Sale de</label>\n          <select onchange=\"CV_SEL.est.origenId=Number(this.value)\">${cfg.origenes.filter(o => o.activo).map(o => `<option value=\"${o.id}\" ${Number(e.origenId) === o.id ? 'selected' : ''}>${escapeHtml(o.nombre)} (CP ${escapeHtml(o.cp)})</option>`).join('')}</select></div>\n        <div class=\"field\" style=\"margin:0;\"><label>CP del cliente</label><input inputmode=\"numeric\" maxlength=\"5\" value=\"${escapeHtml(e.cp || '')}\" oninput=\"CV_SEL.est.cp=this.value\" /></div>\n      </div>\n      <div style=\"display:grid; grid-template-columns:repeat(4, minmax(0, 1fr)); gap:6px; margin-top:8px;\">\n        ${num('peso', 'Peso kg', '0.1')}${num('largo', 'Largo cm', '1')}${num('ancho', 'Ancho cm', '1')}${num('alto', 'Alto cm', '1')}\n      </div>\n      <button type=\"button\" class=\"primary\" style=\"margin-top:8px;\" onclick=\"cv_est_cotizar(this)\">📦 Cotizar envío</button>\n      ${e.error ? `<div class=\"cv-aviso\" style=\"margin-top:8px;\">⚠️ ${escapeHtml(e.error)}</div>` : ''}\n      ${e.res ? `\n        <div style=\"margin-top:8px; display:flex; flex-direction:column; gap:6px;\">\n          ${e.res.servicios.map(sv => `\n            <label style=\"display:flex; gap:8px; align-items:center; text-transform:none; font-weight:400; border:1px solid ${sv.servicio_id === e.servicioId ? 'var(--copper)' : 'rgba(155,157,159,0.35)'}; border-radius:8px; padding:8px 10px; cursor:pointer;\">\n              <input type=\"radio\" name=\"cv_est_srv\" style=\"width:18px; height:18px; flex:0 0 auto; margin:0; accent-color:var(--copper);\" ${sv.servicio_id === e.servicioId ? 'checked' : ''} onchange=\"CV_SEL.est.servicioId='${escapeHtml(sv.servicio_id)}'; cv_renderCotizar()\" />\n              <span style=\"flex:1;\"><b>${escapeHtml(sv.servicio)}</b>${sv.dias ? `<br><span style=\"font-size:11px; color:var(--muted);\">${escapeHtml(String(sv.dias))}</span>` : ''}</span>\n              <span style=\"text-align:right;\"><b>$${cot_fmt(sv.precio)}</b>${sv.costo != null ? `<br><span style=\"font-size:10px; color:var(--muted);\">costo $${cot_fmt(sv.costo)}</span>` : ''}</span>\n            </label>`).join('')}\n          <div style=\"font-size:11px; color:var(--muted);\">Peso volumétrico ${e.res.peso_volumetrico} kg — Estafeta cobra el mayor entre peso real y volumétrico.${cambio ? ' · ⚠️ cambiaste el CP o la sucursal: vuelve a cotizar' : ''}</div>\n          ${s ? `<div style=\"font-size:13px;\">📦 <b>Envío:</b> $${cot_fmt(s.precio)} — ya está sumado al total.</div>` : '<div style=\"font-size:12px; color:var(--muted);\">Elige el servicio para sumarlo al total.</div>'}\n        </div>` : '<div style=\"font-size:11px; color:var(--muted); margin-top:6px;\">Cotiza para ver los servicios de Estafeta y su precio.</div>'}\n    </div>`;\n}\n\nasync function cv_est_cotizar(btn) {\n  const e = CV_SEL.est;\n  await conBloqueoDeBoton(btn, async () => {\n    e.error = '';\n    try {\n      const paquete = { peso: Number(e.peso), largo: Number(e.largo), ancho: Number(e.ancho), alto: Number(e.alto) };\n      const previo = e.res && cv_est_servicio();\n      e.res = await api('/api/estafeta/cotizar', { method: 'POST', body: JSON.stringify({ origen_id: Number(e.origenId), cp_destino: (e.cp || '').trim(), paquete }) });\n      const sigue = previo && e.res.servicios.find(s => s.servicio_id === previo.servicio_id);\n      e.servicioId = sigue ? sigue.servicio_id : (e.res.servicios[0] ? e.res.servicios[0].servicio_id : null);\n      try { localStorage.setItem('cv_est_medidas', JSON.stringify({ peso: e.peso, largo: e.largo, ancho: e.ancho, alto: e.alto })); } catch (x) { /* sin almacenamiento */ }\n    } catch (x) {\n      e.error = x.message;\n      e.res = null; e.servicioId = null;\n    }\n  });\n  cv_renderCotizar();\n}\n\n// ---- Admin: margen, sucursales de envío y estado de la conexión ----\n\nasync function cv_est_cargarAdmin() {\n  const box = document.getElementById('cv_est_cfg');\n  if (!box) return;\n  const cfg = await cv_est_cargarCfg();\n  if (!cfg) { box.remove(); return; }\n  const est = cfg.estado;\n  box.innerHTML = `\n    <div style=\"display:flex; gap:8px; align-items:center; flex-wrap:wrap;\">\n      <b>📦 Estafeta:</b>\n      ${est.conectada ? (est.simulado ? '<span class=\"cv-chip\">🧪 simulado</span>' : `<span style=\"color:#4caf50;\">✔ conectada (${escapeHtml(est.modo)})</span>`)\n        : `<span style=\"color:var(--copper);\">no conectada — faltan en Render: ${escapeHtml(est.faltan.join(', '))}</span>`}\n      <span style=\"margin-left:auto;\">Margen sobre el costo: <input id=\"cv_est_margen\" type=\"number\" min=\"0\" step=\"1\" value=\"${cfg.margen_pct}\" style=\"width:80px; display:inline-block;\" /> %</span>\n      <button class=\"secondary\" style=\"padding:4px 10px;\" onclick=\"cv_est_guardarMargen(this)\">Guardar</button>\n    </div>\n    <div style=\"margin-top:8px; font-size:12px;\">\n      <b>Sucursales de donde salen los paquetes</b> (remitente de la guía):\n      ${cfg.origenes.length ? cfg.origenes.map(o => `\n        <div style=\"display:flex; gap:6px; align-items:center; margin-top:4px;\">\n          <span style=\"flex:1;\">${o.activo ? '' : '<span class=\"cv-chip\">apagada</span> '}<b>${escapeHtml(o.nombre)}</b> — ${escapeHtml([o.calle, o.numero, o.colonia].filter(Boolean).join(' '))}, CP ${escapeHtml(o.cp)}, ${escapeHtml(o.ciudad || '')}</span>\n          <button class=\"secondary\" style=\"padding:2px 8px; font-size:11px;\" onclick=\"cv_est_editarOrigen(${o.id})\">Editar</button>\n        </div>`).join('') : '<span style=\"color:var(--muted);\"> todavía ninguna.</span>'}\n      <div><button class=\"secondary\" style=\"padding:4px 10px; margin-top:6px;\" onclick=\"cv_est_editarOrigen(null)\">+ Sucursal de envío</button></div>\n    </div>`;\n}\n\nasync function cv_est_guardarMargen(btn) {\n  let ok = false;\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      await api('/api/estafeta/config', { method: 'PUT', body: JSON.stringify({ margen_pct: Number(document.getElementById('cv_est_margen').value) || 0 }) });\n      ok = true;\n    } catch (e) { alert(e.message); }\n  });\n  if (ok) { btn.textContent = '✔ Guardado'; setTimeout(() => { btn.textContent = 'Guardar'; }, 2000); }\n}\n\nconst CV_EST_CAMPOS_ORIGEN = [['nombre', 'Nombre de la sucursal *'], ['contacto', 'Contacto (quién entrega)'], ['telefono', 'Teléfono *'],\n  ['calle', 'Calle *'], ['numero', 'Número'], ['colonia', 'Colonia *'], ['cp', 'Código postal *'], ['ciudad', 'Ciudad / municipio *'],\n  ['estado', 'Estado *'], ['referencia', 'Referencias']];\n\nfunction cv_est_editarOrigen(id) {\n  const o = id ? (CV_EST_CFG.origenes || []).find(x => x.id === id) : { activo: true };\n  document.getElementById('modalContent').innerHTML = `\n    <button class=\"close-btn\" onclick=\"cerrarModal()\">cerrar</button>\n    <h2>${id ? 'Editar' : 'Nueva'} sucursal de envío</h2>\n    <p style=\"font-size:12px; color:var(--muted); margin-top:0;\">Es el remitente que sale en la guía de Estafeta.</p>\n    <div class=\"row-2\">${CV_EST_CAMPOS_ORIGEN.map(([k, etq]) => `<div class=\"field\"><label>${etq}</label><input id=\"est_o_${k}\" value=\"${escapeHtml(o[k] || '')}\" ${k === 'cp' ? 'inputmode=\"numeric\" maxlength=\"5\"' : ''} /></div>`).join('')}</div>\n    <label style=\"text-transform:none; font-weight:400; display:flex; gap:6px; align-items:center;\"><input type=\"checkbox\" id=\"est_o_activo\" ${o.activo ? 'checked' : ''} /> Activa (los vendedores la pueden elegir)</label>\n    <div style=\"display:flex; gap:8px; margin-top:14px;\">\n      <button class=\"primary\" style=\"flex:1;\" onclick=\"cv_est_guardarOrigen(${id || 'null'}, this)\">Guardar</button>\n      ${id ? `<button class=\"secondary\" style=\"color:var(--copper); border-color:var(--copper);\" onclick=\"cv_est_borrarOrigen(${id})\">Borrar</button>` : ''}\n    </div>`;\n  abrirModal();\n}\n\nasync function cv_est_guardarOrigen(id, btn) {\n  const datos = { activo: document.getElementById('est_o_activo').checked };\n  CV_EST_CAMPOS_ORIGEN.forEach(([k]) => { datos[k] = document.getElementById(`est_o_${k}`).value.trim() || null; });\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      await api(id ? `/api/estafeta/origenes/${id}` : '/api/estafeta/origenes', { method: id ? 'PUT' : 'POST', body: JSON.stringify(datos) });\n      cerrarModal();\n      await cv_est_cargarAdmin();\n    } catch (e) { alert(e.message); }\n  });\n}\n\nasync function cv_est_borrarOrigen(id) {\n  if (!confirm('¿Borrar esta sucursal de envío? (las guías ya hechas no se pierden)')) return;\n  try {\n    await api(`/api/estafeta/origenes/${id}`, { method: 'DELETE' });\n    cerrarModal();\n    await cv_est_cargarAdmin();\n  } catch (e) { alert(e.message); }\n}\n\n// ---- Guía y rastreo (desde una cotización) ----\n\nlet EST_G = null;\nconst EST_CAMPOS_DESTINO = [['nombre', 'Destinatario (empresa o persona) *'], ['contacto', 'Contacto'], ['telefono', 'Teléfono *'], ['correo', 'Correo'],\n  ['calle', 'Calle *'], ['numero', 'Número'], ['colonia', 'Colonia *'], ['cp', 'Código postal *'], ['ciudad', 'Ciudad / municipio *'],\n  ['estado', 'Estado *'], ['referencia', 'Referencias (entre calles, color de fachada…)']];\n\nasync function est_abrirGuia(cotizacionId, folio) {\n  document.getElementById('modalContent').innerHTML = '<p style=\"font-size:13px;\">Cargando…</p>';\n  abrirModal(true);\n  try {\n    const d = await api(`/api/cotizaciones/${cotizacionId}/estafeta`);\n    const env = d.envio || {};\n    const p = env.paquete || {};\n    EST_G = { id: cotizacionId, folio: folio || '', d, destino: { ...d.destino_sugerido },\n              origenId: env.origen_id || (d.origenes[0] && d.origenes[0].id) || null,\n              paquete: { peso: p.peso || '', largo: p.largo || '', ancho: p.ancho || '', alto: p.alto || '' },\n              servicioId: env.servicio_id || null, servicio: env.servicio || '', servicios: null, contenido: 'Equipo dental',\n              error: '', rastreo: {} };\n    est_render();\n  } catch (e) {\n    document.getElementById('modalContent').innerHTML = `<button class=\"close-btn\" onclick=\"cerrarModal()\">cerrar</button><div class=\"cv-aviso\">⚠️ ${escapeHtml(e.message)}</div>`;\n  }\n}\n\nfunction est_render() {\n  const g = EST_G, d = g.d;\n  const listaServicios = g.servicios || (g.servicioId ? [{ servicio_id: g.servicioId, servicio: g.servicio || g.servicioId }] : []);\n  document.getElementById('modalContent').innerHTML = `\n    <button class=\"close-btn\" onclick=\"cerrarModal()\">cerrar</button>\n    <h2 style=\"margin-bottom:4px;\">📦 Guía Estafeta</h2>\n    <p style=\"font-size:13px; color:var(--muted); margin-top:0;\">Cotización <b>${escapeHtml(g.folio)}</b>${d.envio ? ` · cotizado: ${escapeHtml(d.envio.servicio || '')} $${cot_fmt(d.envio.precio || 0)}` : ' · no se cotizó envío al crearla'}</p>\n    ${d.estado.simulado ? '<div class=\"cv-aviso\">🧪 Modo SIMULADO: la guía es de prueba, NO sirve para enviar.</div>' : ''}\n    ${!d.estado.modo ? '<div class=\"cv-aviso\">Estafeta todavía no está conectada (faltan las credenciales en Render).</div>' : ''}\n    ${d.guias.length ? `\n      <span class=\"cv-etq\">Guías de esta cotización</span>\n      ${d.guias.map(x => `\n        <div class=\"cv-caja\" style=\"margin-bottom:6px;\">\n          <div style=\"display:flex; gap:6px; align-items:center; flex-wrap:wrap;\">\n            <b style=\"flex:1;\">${escapeHtml(x.numero_guia)}${x.simulada ? ' <span class=\"cv-chip\">simulada</span>' : ''}</b>\n            <span style=\"font-size:12px; color:var(--muted);\">${escapeHtml(x.servicio || '')} · ${escapeHtml((x.creado_en || '').slice(0, 16).replace('T', ' '))}</span>\n            <button class=\"secondary\" style=\"padding:4px 10px;\" onclick=\"est_descargarPdf(${x.id}, '${escapeHtml(x.numero_guia)}')\">📄 PDF</button>\n            <button class=\"secondary\" style=\"padding:4px 10px;\" onclick=\"est_rastrear(${x.id}, this)\">🔎 Rastrear</button>\n          </div>\n          ${g.rastreo[x.id] ? `<div style=\"font-size:12px; margin-top:6px;\"><b>${escapeHtml(g.rastreo[x.id].estatus)}</b>\n            ${(g.rastreo[x.id].eventos || []).map(ev => `<div style=\"color:var(--muted);\">${escapeHtml((ev.fecha || '').replace('T', ' '))} — ${escapeHtml(ev.descripcion)}${ev.lugar ? ` (${escapeHtml(ev.lugar)})` : ''}</div>`).join('')}\n            <a href=\"${escapeHtml(g.rastreo[x.id].url)}\" target=\"_blank\" rel=\"noopener\">Ver en estafeta.com</a></div>`\n            : (x.ultimo_estatus ? `<div style=\"font-size:12px; color:var(--muted); margin-top:4px;\">Último estatus: ${escapeHtml(x.ultimo_estatus)}</div>` : '')}\n        </div>`).join('')}` : ''}\n\n    <span class=\"cv-etq\">${d.guias.length ? 'Generar otra guía' : 'Generar guía'}</span>\n    ${g.error ? `<div class=\"cv-aviso\">⚠️ ${escapeHtml(g.error)}</div>` : ''}\n    <div class=\"row-2\">\n      <div class=\"field\"><label>Sale de</label>\n        <select onchange=\"EST_G.origenId=Number(this.value); EST_G.servicios=null\">${d.origenes.map(o => `<option value=\"${o.id}\" ${Number(g.origenId) === o.id ? 'selected' : ''}>${escapeHtml(o.nombre)} (CP ${escapeHtml(o.cp)})</option>`).join('')}</select></div>\n      <div class=\"field\"><label>Contenido</label><input value=\"${escapeHtml(g.contenido)}\" maxlength=\"25\" oninput=\"EST_G.contenido=this.value\" /></div>\n    </div>\n    <div style=\"display:grid; grid-template-columns:repeat(4, minmax(0, 1fr)); gap:6px;\">\n      ${['peso', 'largo', 'ancho', 'alto'].map(k => `<div class=\"field\" style=\"margin:0;\"><label>${{ peso: 'Peso kg', largo: 'Largo cm', ancho: 'Ancho cm', alto: 'Alto cm' }[k]}</label><input type=\"number\" min=\"0\" step=\"${k === 'peso' ? '0.1' : '1'}\" value=\"${escapeHtml(String(g.paquete[k] ?? ''))}\" oninput=\"EST_G.paquete['${k}']=this.value; EST_G.servicios=null\" /></div>`).join('')}\n    </div>\n    <div style=\"display:flex; gap:6px; align-items:flex-end; margin-top:8px; flex-wrap:wrap;\">\n      <div class=\"field\" style=\"margin:0; flex:1; min-width:200px;\"><label>Servicio</label>\n        <select onchange=\"EST_G.servicioId=this.value; EST_G.servicio=this.options[this.selectedIndex].dataset.nombre\">\n          ${listaServicios.length ? listaServicios.map(s => `<option value=\"${escapeHtml(s.servicio_id)}\" data-nombre=\"${escapeHtml(s.servicio)}\" ${s.servicio_id === g.servicioId ? 'selected' : ''}>${escapeHtml(s.servicio)}${s.precio != null ? ` — $${cot_fmt(s.precio)}` : ''}</option>`).join('') : '<option value=\"\">— cotiza primero —</option>'}\n        </select></div>\n      <button class=\"secondary\" onclick=\"est_recotizar(this)\">Ver servicios</button>\n    </div>\n    <span class=\"cv-etq\">Destinatario</span>\n    <div class=\"row-2\">${EST_CAMPOS_DESTINO.map(([k, etq]) => `<div class=\"field\"><label>${etq}</label><input value=\"${escapeHtml(g.destino[k] || '')}\" ${k === 'cp' ? 'inputmode=\"numeric\" maxlength=\"5\"' : ''} oninput=\"EST_G.destino['${k}']=this.value\" /></div>`).join('')}</div>\n    <button class=\"primary\" style=\"width:100%; margin-top:6px;\" onclick=\"est_generar(this)\">📦 Generar guía</button>\n  `;\n}\n\nasync function est_recotizar(btn) {\n  const g = EST_G;\n  await conBloqueoDeBoton(btn, async () => {\n    g.error = '';\n    try {\n      const r = await api('/api/estafeta/cotizar', { method: 'POST', body: JSON.stringify({ origen_id: Number(g.origenId), cp_destino: (g.destino.cp || '').trim(),\n        paquete: { peso: Number(g.paquete.peso), largo: Number(g.paquete.largo), ancho: Number(g.paquete.ancho), alto: Number(g.paquete.alto) } }) });\n      g.servicios = r.servicios;\n      const sigue = r.servicios.find(s => s.servicio_id === g.servicioId) || r.servicios[0];\n      g.servicioId = sigue ? sigue.servicio_id : null;\n      g.servicio = sigue ? sigue.servicio : '';\n    } catch (e) { g.error = e.message; }\n  });\n  est_render();\n}\n\nasync function est_generar(btn) {\n  const g = EST_G;\n  if (!g.servicioId) { g.error = 'Elige el servicio (botón \"Ver servicios\").'; est_render(); return; }\n  if (!confirm('¿Generar la guía? Estafeta la cobra a tu cuenta.')) return;\n  await conBloqueoDeBoton(btn, async () => {\n    g.error = '';\n    try {\n      const r = await api(`/api/cotizaciones/${g.id}/estafeta/guia`, { method: 'POST', body: JSON.stringify({\n        origen_id: Number(g.origenId), servicio_id: g.servicioId, servicio: g.servicio || null, contenido: g.contenido || null,\n        paquete: { peso: Number(g.paquete.peso), largo: Number(g.paquete.largo), ancho: Number(g.paquete.ancho), alto: Number(g.paquete.alto) },\n        destino: g.destino }) });\n      g.d.guias = r.guias;\n      await est_descargarPdf(r.id, r.numero_guia);\n    } catch (e) { g.error = e.message; }\n  });\n  est_render();\n}\n\nasync function est_descargarPdf(guiaId, numero) {\n  try {\n    const r = await fetch(`/api/estafeta/guias/${guiaId}/pdf`, { headers: headers(false) });\n    if (!r.ok) throw new Error('No se pudo descargar la guía');\n    const url = URL.createObjectURL(await r.blob());\n    const a = document.createElement('a');\n    a.href = url; a.download = `guia_estafeta_${numero}.pdf`;\n    document.body.appendChild(a); a.click(); a.remove();\n    URL.revokeObjectURL(url);\n  } catch (e) { alert(e.message); }\n}\n\nasync function est_rastrear(guiaId, btn) {\n  await conBloqueoDeBoton(btn, async () => {\n    try { EST_G.rastreo[guiaId] = await api(`/api/estafeta/guias/${guiaId}/rastreo`); }\n    catch (e) { EST_G.error = e.message; }\n  });\n  est_render();\n}\n\n// ---------- Conceptos libres (envío, paquetería, instalación…) ----------\n"
